files = sorted(glob.glob('src/data/*.js'))
src = {f: open(f).read() for f in files}
done = 0
miss = []
for eid, old, new, ko in R:
    hit = False
    for f in files:
        s = src[f]
        m = re.search(r"id: '%s'," % re.escape(eid), s)
        if not m: continue
        nxt = re.search(r"\n  \{\n    id: '|\n  \{ id: '", s[m.end():])
        end = m.end() + (nxt.start() if nxt else len(s) - m.end())
        block = s[m.start():end]
        pat = re.compile(r"'%s',(\s*)'([^']*)'" % re.escape(old))
        mm = pat.search(block)
        if not mm:
            break
        rep = "'%s',%s'%s'" % (new, mm.group(1), ko)
        block = block[:mm.start()] + rep + block[mm.end():]
        src[f] = s[:m.start()] + block + s[end:]
        hit = True
        done += 1
        break
    if not hit: miss.append((eid, old[:30]))
for f in files: open(f, 'w').write(src[f])
print('applied', done, 'missing', len(miss))
for x in miss: print('  ', x)
